const { getState, getProps } = options;
const { favoriteSearch } = getState();
const favorites = getProps().favorites;
const favorite = favorites[favoriteSearch];
const isDisabled = !favorite && (!window.currentSearchMode || window.currentSearchMode.name === 'NoUI');
let image = 'FavoriteOff.svg';
let tooltip = 'favorite_button.save_search';
if (favorite) {
	image = 'FavoriteOn.svg';
	tooltip = 'favorite_button.edit_favorite';
}

return {
	disabled: isDisabled,
	image: '../images/' + image,
	tooltip_template: aras.getResource('', tooltip)
};
